const raw = $input.first().json['Songs'];
const songs = raw.split('\n').map(s => s.trim()).filter(s => s.length > 0);
if (songs.length === 0) throw new Error('No input provided!');
return [{ json: { queries: songs } }];

const data = $input.first().json;
const results = data.results || [];
const summary = {
  status: data.status,
  total: results.length,
  downloaded: results.filter(r => r.status === 'success').length,
  skipped: results.filter(r => r.status === 'skipped').length,
  failed: results.filter(r => r.status === 'error').length,
  tracks: results.map(r => ({ query: r.query, title: r.title, status: r.status }))
};
return [{ json: summary }];
